import sys
import numpy as np
import xarray as xr

path=[]
active_frame=None

def tracer(frame,event,arg):
    global active_frame
    if event=='call':
        code=frame.f_code
        if code.co_name=='construct' and code.co_filename.endswith('/xarray/computation/rolling.py') and code.co_firstlineno==922:
            active_frame=frame
            return tracer
